import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }

record CellIter { i: Int64, hi: Int64 }

impl Iterator<Cell> for CellIter {
    pub fn next(mut self) -> Option<Cell> {
        if self.i >= self.hi { return None }
        let c = Cell { n: self.i }
        self.i = self.i + 1
        return Some(c)
    }
}

record Gen { hi: Int64 }

impl Iterable<Cell> for Gen {
    type Iter = CellIter
    pub fn iterator(self) -> CellIter { return CellIter { i: 0, hi: self.hi } }
}

pub fn main() effect io -> Result<(), AppError> {
    let g = Gen { hi: 8 }
    let ds = g.iterator().collect()

    var i: Int64 = 0
    while i < 120000 {
        let pad = Cell { n: 999999 }
        i = i + 1
    }

    for d in ds { io.println("${d.n}") }
    return Ok(())
}
